   ,parameter           p_CDC_EN            = 1 
   ,parameter           p_CHKBIT_WIDTH      = 8      
   ,parameter   [15:0]  p_PRO_NUM           = 16'h001C
   ,parameter   [3:0]   p_MAR_VER           = 4'h1        
   ,parameter   [3:0]   p_MIR_VER           = 4'h0 
   ,parameter           p_RAM_DATA_WIDTH    = 64
   ,parameter           p_RAM_DBYTE_NUM     = p_RAM_DATA_WIDTH/8
)(
    input   wire                            clk          
   ,input   wire                            rst_n         
   ,input   wire    [p_AHB_ADDR_WIDTH-1:0]  i_addr      
   ,input   wire    [p_AHB_DATA_WIDTH-1:0]  i_wdata     
   ,input   wire                            i_read_en   
   ,input   wire                            i_write_en  
   ,input   wire    [3:0]                   i_wstrobe   
   ,input   wire                            i_priority  
   ,output  wire    [p_AHB_DATA_WIDTH-1:0]  o_rdata     
