   ,input   wire    [15:0]                  i_r0_addr   
   ,input   wire                            i_r1_rden   
   ,input   wire    [15:0]                  i_r1_addr   
   ,output  wire                            o_go            
   ,output  wire    [12:0]                  o_partial_radix 
   ,output  wire    [7:0]                   o_base_radix   
   ,output  wire    [11:0]                  o_addr          
   ,input   wire    [11:0]                  i_rom_addr      
   ,input   wire    [8:0]                   i_core_ris      
   ,output  wire    [8:0]                   o_core_done_clr     
   ,output  wire    [8:0]                   o_core_irqen    
   ,input   wire    [3:0]                   i_stop_log      
   ,output  wire    [31:0]                  o_seed          
   ,output  wire                            o_rc_en         
   ,output  wire    [15:0]                  o_rc_key        
   ,output  wire    [31:0]                  o_rc_data_nonce 
   ,output  wire    [31:0]                  o_rc_addr_nonce 
   ,input   wire    [p_RAM_DATA_WIDTH-1:0]  i_ram0_rd_dat   
   ,output  wire    [15:0]                  o_ram0_rd_addr  
