   ,output  wire    [p_RAM_DATA_WIDTH-1:0]  o_ram0_wr_dat   
   ,output  wire    [15:0]                  o_ram0_wr_addr  
   ,output  wire                            o_ram0_wr_en
   ,output  wire    [p_RAM_DBYTE_NUM-1:0]   o_ram0_wbe     
