   ,output  wire                            o_ram1_rd_en    
   ,output  wire    [p_RAM_DATA_WIDTH-1:0]  o_ram1_wr_dat   
   ,output  wire    [15:0]                  o_ram1_wr_addr  
   ,output  wire                            o_ram1_wr_en   
   ,output  wire    [p_RAM_DBYTE_NUM-1:0]   o_ram1_wbe  
   ,output  wire    [31:0]                  o_ram_ecc_en
   ,output  wire    [31:0]                  o_ram_ecctest_en
