    wire    [15:0]      w_r1_waddr          ;
    wire    [15:0]      w_r1_waddr_o        ;
    wire                w_r1_rden           ;
    wire    [31:0]      w_r1_rdat           ;
    wire    [15:0]      w_r1_raddr          ;
    wire    [31:0]                  w_ram_ecc_en    ;
    wire    [31:0]                  w_ram_ecctest_en;
    wire    [4*p_CHKBIT_WIDTH-1:0]  w_ram_ecc_chkbit;
    wire                w_ban_in            ;
    reg                 r_ban               ;
    reg                 r_core_done_dly     ;
    wire                w_priority_NC       ;
    wire    [11:0]      w_rom_addr_NC       ;
