    wire    w_adr_eq_ram2_ecc       =
                {i_addr[p_AHB_ADDR_WIDTH-1:2],2'b00} == p_ADDR_RAM2_ECC ;
    wire    w_adr_eq_ram3_ecc       =
                {i_addr[p_AHB_ADDR_WIDTH-1:2],2'b00} == p_ADDR_RAM3_ECC ;
    assign w_wsel[p_PKE_HP_SEL_BASE+12] = w_adr_eq_ram0_ecc & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+13] = w_adr_eq_ram1_ecc & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+14] = w_adr_eq_ram2_ecc & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+15] = w_adr_eq_ram3_ecc & i_write_en & (!r_ban);
    assign w_ram0_ecc_in = w_wsel[p_PKE_HP_SEL_BASE+12] ? i_wdata[p_CHKBIT_WIDTH+15:0] : r_ram0_ecc;
    assign w_ram1_ecc_in = w_wsel[p_PKE_HP_SEL_BASE+13] ? i_wdata[p_CHKBIT_WIDTH+15:0] : r_ram1_ecc;
    assign w_ram2_ecc_in = w_wsel[p_PKE_HP_SEL_BASE+14] ? i_wdata[p_CHKBIT_WIDTH+15:0] : r_ram2_ecc;
    assign w_ram3_ecc_in = w_wsel[p_PKE_HP_SEL_BASE+15] ? i_wdata[p_CHKBIT_WIDTH+15:0] : r_ram3_ecc;
    always@(posedge clk or negedge rst_n)
    begin
        if(!rst_n) begin
            r_ram0_ecc   <= {(p_CHKBIT_WIDTH+16){1'b0}};     
            r_ram1_ecc   <= {(p_CHKBIT_WIDTH+16){1'b0}};
            r_ram2_ecc   <= {(p_CHKBIT_WIDTH+16){1'b0}};
            r_ram3_ecc   <= {(p_CHKBIT_WIDTH+16){1'b0}};
        end
        else begin
            r_ram0_ecc   <=  w_ram0_ecc_in; 
            r_ram1_ecc   <=  w_ram1_ecc_in; 
            r_ram2_ecc   <=  w_ram2_ecc_in; 
            r_ram3_ecc   <=  w_ram3_ecc_in;
        end 
    end
    assign w_ram_ecc_en     = {r_ram3_ecc[7:0],r_ram2_ecc[7:0],r_ram1_ecc[7:0],r_ram0_ecc[7:0]};
    assign w_ram_ecctest_en = {r_ram3_ecc[15:8],r_ram2_ecc[15:8],r_ram1_ecc[15:8],r_ram0_ecc[15:8]};
    assign w_ram_ecc_chkbit = {r_ram3_ecc[p_CHKBIT_WIDTH+15:16],r_ram2_ecc[p_CHKBIT_WIDTH+15:16],
                               r_ram1_ecc[p_CHKBIT_WIDTH+15:16],r_ram0_ecc[p_CHKBIT_WIDTH+15:16]};
    assign o_rdata = w_adr_eq_ram0_ecc ? {{(16-p_CHKBIT_WIDTH){1'b0}}, r_ram0_ecc}:
                     w_adr_eq_ram1_ecc ? {{(16-p_CHKBIT_WIDTH){1'b0}}, r_ram1_ecc}:
                     w_adr_eq_ram2_ecc ? {{(16-p_CHKBIT_WIDTH){1'b0}}, r_ram2_ecc}:
                     w_adr_eq_ram3_ecc ? {{(16-p_CHKBIT_WIDTH){1'b0}}, r_ram3_ecc}:
                     w_rdata;
    end
    else 
    begin : g_no_ecc_reg
        assign w_ram_ecc_en     = 32'b0;
        assign w_ram_ecctest_en = 32'b0;
        assign w_ram_ecc_chkbit = 2'b0;
        assign o_rdata          = w_rdata;
    end
    endgenerate
    assign w_wsel[p_PKE_HP_SEL_BASE+0 ] = w_adr_eq_ctrl     & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+1 ] = w_adr_eq_cfg      & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+2 ] = w_adr_eq_mc_ptr   & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+3 ] = w_adr_eq_risr     & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+4 ] = w_adr_eq_imcr     & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+5 ] = w_adr_eq_rnd_sd   & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+6 ] = w_adr_eq_rc_en    & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+7 ] = w_adr_eq_rc_key   & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+8 ] = w_adr_eq_rc_data_nonce
                                                            & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+9 ] = w_adr_eq_rc_addr_nonce
                                                            & i_write_en & (!r_ban);
    assign w_wsel[p_PKE_HP_SEL_BASE+10] = w_adr_eq_ram0     & i_write_en;
    assign w_wsel[p_PKE_HP_SEL_BASE+11] = w_adr_eq_ram1     & i_write_en;
    assign w_go_in = 
            w_wsel[p_PKE_HP_SEL_BASE+0] && i_wstrobe[0] && i_wdata[0] ? 1'b1 :
                                                                        1'b0;
    assign w_go_ff_in = 
            w_wsel[p_PKE_HP_SEL_BASE+0] && i_wstrobe[0]  ? i_wdata[0] :
                                                           r_go_ff;
    assign w_partial_radix_in[7:0] = 
            w_wsel[p_PKE_HP_SEL_BASE+1] && i_wstrobe[0] ? i_wdata[7:0] : 
                                                          r_partial_radix[7:0];
    assign w_partial_radix_in[12:8] = 
            w_wsel[p_PKE_HP_SEL_BASE+1] && i_wstrobe[1] ? i_wdata[12:8] : 
                                                          r_partial_radix[12:8];
    assign w_base_radix_in = 
            w_wsel[p_PKE_HP_SEL_BASE+1] && i_wstrobe[2] ? i_wdata[18:16] : 
                                                          r_base_radix;
    assign w_base_radix = 
            r_base_radix==3'd2 ? 8'd3  :
            r_base_radix==3'd3 ? 8'd7  :
            r_base_radix==3'd4 ? 8'd15 :
            r_base_radix==3'd5 ? 8'd31 :
            r_base_radix==3'd6 ? 8'd63 : 
                                 8'd0;
    assign w_partial_radix_m1 = r_partial_radix-1'b1;
    assign w_partial_radix = ((w_partial_radix_m1[12:8]+1)<<2)-1'b1+13'd0;
    assign w_addr_in[7:0]  = 
            w_wsel[p_PKE_HP_SEL_BASE+2] && i_wstrobe[0] ? i_wdata[7:0]  : 
                                                          r_addr[7:0];
    assign w_addr_in[11:8]  = 
            w_wsel[p_PKE_HP_SEL_BASE+2] && i_wstrobe[1] ? i_wdata[11:8]  : 
                                                          r_addr[11:8];
    assign w_core_done_clr[0] = 
            w_wsel[p_PKE_HP_SEL_BASE+3] & i_wstrobe[0] ? (~i_wdata[0]) : 1'b0;
    assign w_core_done_clr[4:1] = 
            w_wsel[p_PKE_HP_SEL_BASE+3] & i_wstrobe[1] ? (~i_wdata[11:8]) : 4'b0;
    assign w_core_done_clr[8:5] = 
            w_wsel[p_PKE_HP_SEL_BASE+3] & i_wstrobe[2] ? (~i_wdata[19:16]): 4'b0;
    assign w_core_done_clr_in = 
            w_wsel[p_PKE_HP_SEL_BASE+3] ? w_core_done_clr : r_core_done_clr;
    assign w_core_irqen_in  = 
            w_wsel[p_PKE_HP_SEL_BASE+4] && i_wstrobe[0] ? {i_wdata[19:16], i_wdata[11:8], i_wdata[0]} : 
                                                          r_core_irqen;
    assign w_core_mi = r_core_irqen & i_core_ris;
    assign w_seed_in[7:0] = 
            w_wsel[p_PKE_HP_SEL_BASE+5] && i_wstrobe[0] ? i_wdata[7:0]: 
                                                          r_seed[7:0];
    assign w_seed_in[15:8] = 
            w_wsel[p_PKE_HP_SEL_BASE+5] && i_wstrobe[1] ? i_wdata[15:8]: 
                                                          r_seed[15:8];
    assign w_seed_in[23:16] = 
            w_wsel[p_PKE_HP_SEL_BASE+5] && i_wstrobe[2] ? i_wdata[23:16]: 
                                                          r_seed[23:16];
    assign w_seed_in[31:24] = 
            w_wsel[p_PKE_HP_SEL_BASE+5] && i_wstrobe[3] ? i_wdata[31:24]: 
                                                          r_seed[31:24];
    assign w_r0_wbe   = !w_r0_waddr[3] ? ( w_r0_waddr[2] ? {i_wstrobe,4'b0} : {4'b0, i_wstrobe}) :
                         w_r1_waddr[3] ? ( w_r1_waddr[2] ? {i_wstrobe,4'b0} : {4'b0, i_wstrobe}) : 
                         {p_RAM_DBYTE_NUM{1'b0}};
    assign w_r0_wdat  = i_addr[3:2]==2'b00 ? {32'd0,i_wdata} :
                        i_addr[3:2]==2'b01 ? {i_wdata,32'd0} : 
                        i_addr[3:2]==2'b10 ? {32'd0,i_wdata} :
                        i_addr[3:2]==2'b11 ? {i_wdata,32'd0} : 
                                             {p_RAM_DATA_WIDTH{1'b0}};
    assign w_r0_waddr = i_addr-p_ADDR_R0_LB+16'd0;
    assign w_r0_waddr_o = 
                                            (!w_r0_waddr[3]) ? 
                        {7'b0, w_r0_waddr[11:3]} : 
                                              w_r1_waddr[3]  ? 
                        {7'b0, w_r1_waddr[11:3]} : 
                        16'b0;
    assign w_r0_wren  = 
            w_wsel[p_PKE_HP_SEL_BASE+10] && (!w_r0_waddr[3]) ? 1'b1 : 
            w_wsel[p_PKE_HP_SEL_BASE+11] &&   w_r1_waddr[3]  ? 1'b1 : 
                                                               1'b0 ;
    assign w_r0_raddr = 
                         (!i_r0_addr[3]) ? {7'b0, i_r0_addr[11:3]} :
                           i_r1_addr[3]  ? {7'b0, i_r1_addr[11:3]} : 
                                           16'd0;
    assign w_r0_rdat  = i_addr[3:2]==2'b00 ? i_ram0_rd_dat[31: 0] :
                        i_addr[3:2]==2'b01 ? i_ram0_rd_dat[63:32] :
                        i_addr[3:2]==2'b10 ? i_ram1_rd_dat[31: 0] :
                        i_addr[3:2]==2'b11 ? i_ram1_rd_dat[63:32] : 
                                             32'd0;
    assign w_r0_rden = 
            i_r0_rden && (!i_r0_addr[3]) ? 1'b1 :
            i_r1_rden &&   i_r1_addr[3]  ? 1'b1 : 
                                           1'b0; 
    assign w_r1_wbe   =  w_r0_waddr[3] ? ( w_r1_waddr[2] ? {i_wstrobe,4'b0} : {4'b0, i_wstrobe}) :
                        !w_r1_waddr[3] ? ( w_r0_waddr[2] ? {i_wstrobe,4'b0} : {4'b0, i_wstrobe}) : 
                         {p_RAM_DBYTE_NUM{1'b0}};
    assign w_r1_wdat  = i_addr[3:2]==2'b00 ? {32'd0,i_wdata} :
                        i_addr[3:2]==2'b01 ? {i_wdata,32'd0} : 
                        i_addr[3:2]==2'b10 ? {32'd0,i_wdata} :
                        i_addr[3:2]==2'b11 ? {i_wdata,32'd0} : 
                                             {p_RAM_DATA_WIDTH{1'b0}}; 
    assign w_r1_waddr = i_addr-p_ADDR_R1_LB+16'd0;
    assign w_r1_waddr_o = 
                                              w_r0_waddr[3]  ? 
                        {7'd0, w_r0_waddr[11:3]} : 
                                            (!w_r1_waddr[3]) ? 
                        {7'd0, w_r1_waddr[11:3]} :
                        16'b0;
    assign w_r1_wren  = 
            w_wsel[p_PKE_HP_SEL_BASE+10] &&   w_r0_waddr[3]  ? 1'b1 : 
            w_wsel[p_PKE_HP_SEL_BASE+11] && (!w_r1_waddr[3]) ? 1'b1 : 
                                                               1'b0 ;
    assign w_r1_raddr = 
                           i_r0_addr[3]  ? {7'd0, i_r0_addr[11:3]} :
                         (!i_r1_addr[3]) ? {7'd0, i_r1_addr[11:3]} : 
                                           16'd0;
    assign w_r1_rdat  = i_addr[3:2]==2'b00 ? i_ram1_rd_dat[31: 0] :
                        i_addr[3:2]==2'b01 ? i_ram1_rd_dat[63:32] :
                        i_addr[3:2]==2'b10 ? i_ram0_rd_dat[31: 0] :
                        i_addr[3:2]==2'b11 ? i_ram0_rd_dat[63:32] :
                                             32'd0;
    assign w_r1_rden = 
            i_r0_rden &&   i_r0_addr[3]  ? 1'b1 :
            i_r1_rden && (!i_r1_addr[3]) ? 1'b1 : 
                                           1'b0; 
    assign w_rc_en_in = 
            w_wsel[p_PKE_HP_SEL_BASE+6] && i_wstrobe[0] ? i_wdata[0] : 
                                                            r_rc_en;
    assign w_rc_en1_in = r_rc_en && (!w_rc_update);
    assign w_rc_key_in[7:0] = 
            w_wsel[p_PKE_HP_SEL_BASE+7] && i_wstrobe[0] ? i_wdata[7:0]: 
                                                            r_rc_key[7:0];
    assign w_rc_key_in[15:8] = 
            w_wsel[p_PKE_HP_SEL_BASE+7] && i_wstrobe[1] ? i_wdata[15:8]: 
                                                            r_rc_key[15:8];
    assign w_rc_data_nonce_in[7:0] = 
            w_wsel[p_PKE_HP_SEL_BASE+8] && i_wstrobe[0] ? i_wdata[7:0]: 
                                                        r_rc_data_nonce[7:0];
    assign w_rc_data_nonce_in[15:8] = 
            w_wsel[p_PKE_HP_SEL_BASE+8] && i_wstrobe[1] ? i_wdata[15:8]: 
                                                        r_rc_data_nonce[15:8];
    assign w_rc_data_nonce_in[23:16] = 
            w_wsel[p_PKE_HP_SEL_BASE+8] && i_wstrobe[2] ? i_wdata[23:16]: 
                                                        r_rc_data_nonce[23:16];
    assign w_rc_data_nonce_in[31:24] = 
            w_wsel[p_PKE_HP_SEL_BASE+8] && i_wstrobe[3] ? i_wdata[31:24]: 
                                                        r_rc_data_nonce[31:24];
    assign w_rc_addr_nonce_in[7:0] = 
            w_wsel[p_PKE_HP_SEL_BASE+9] && i_wstrobe[0] ? i_wdata[7:0]: 
                                                        r_rc_addr_nonce[7:0];
    assign w_rc_addr_nonce_in[15:8] = 
            w_wsel[p_PKE_HP_SEL_BASE+9] && i_wstrobe[1] ? i_wdata[15:8]: 
                                                        r_rc_addr_nonce[15:8];
    assign w_rc_addr_nonce_in[23:16] = 
            w_wsel[p_PKE_HP_SEL_BASE+9] && i_wstrobe[2] ? i_wdata[23:16]: 
                                                        r_rc_addr_nonce[23:16];
    assign w_rc_addr_nonce_in[31:24] = 
            w_wsel[p_PKE_HP_SEL_BASE+9] && i_wstrobe[3] ? i_wdata[31:24]: 
                                                        r_rc_addr_nonce[31:24];
    assign w_rc_update = (w_wsel[p_PKE_HP_SEL_BASE+6] | 
                          w_wsel[p_PKE_HP_SEL_BASE+7] |
                          w_wsel[p_PKE_HP_SEL_BASE+8]) && (|i_wstrobe);
    generate
    if(p_CDC_EN)
    begin: g_cdc_release
        assign w_hready_rls = 
                i_read_en && w_adr_eq_ctrl  ? 1'b1 :
                (w_go_in || r_go_ff) && w_adr_eq_ctrl
                                            ? i_cdc_hready_rls :
                i_read_en && w_adr_eq_risr  ? 1'b1 :
                ((|w_core_done_clr) || (|r_core_done_clr)) && w_adr_eq_risr
                                            ? i_cdc_hready_rls :
                w_adr_eq_ram0 || w_adr_eq_ram1 ? 
                                              i_cdc_hready_rls 
                                               : 1'b1;
    end
    else
    begin: g_nocdc_release
        assign w_hready_rls = w_adr_eq_ram0 || w_adr_eq_ram1 ? i_cdc_hready_rls : 1'b1;
    end
    endgenerate
    assign w_ban_in = r_go                              ? 1'b1 :
                      i_core_ris[0] & (!r_core_done_dly)? 1'b0 :
                                                          r_ban;   
    always@(posedge clk or negedge rst_n)
    begin
        if(!rst_n) begin
            r_go            <= 1'd0;
            r_go_ff         <= 1'd0;
            r_core_irqen    <= 9'b0;
            r_partial_radix <= 13'd256;
            r_base_radix    <= 3'd2;
            r_addr          <= 12'd0;
            r_seed          <= 32'h628a92e1;
            r_rc_en         <= 1'b0;
            r_rc_en1        <= 1'b0;
            r_rc_key        <= 16'd0;
            r_rc_data_nonce <= 32'd0;
            r_rc_addr_nonce <= 32'd0;
            r_core_done_clr <= 9'd0;
            r_ban           <= 1'd0;
            r_core_done_dly <= 1'd0;
        end
        else begin
            r_go            <=  w_go_in;
            r_go_ff         <=  w_go_ff_in;
            r_core_irqen    <=  w_core_irqen_in;
            r_partial_radix <=  w_partial_radix_in;
            r_base_radix    <=  w_base_radix_in;
            r_addr          <=  w_addr_in;
            r_seed          <=  w_seed_in;
            r_rc_en         <=  w_rc_en_in;
            r_rc_en1        <=  w_rc_en1_in;
            r_rc_key        <=  w_rc_key_in;
            r_rc_data_nonce <=  w_rc_data_nonce_in;
            r_rc_addr_nonce <=  w_rc_addr_nonce_in;
            r_core_done_clr <=  w_core_done_clr_in;
            r_ban           <=  w_ban_in; 
            r_core_done_dly <=  i_core_ris[0];
        end
    end
    always@(*) begin
        w_rdata = 32'h0;
        case(1'b1)
            w_adr_eq_ctrl       : w_rdata = {31'd0,r_go};
            w_adr_eq_cfg        : w_rdata = 
                {13'd0,r_base_radix,3'd0,r_partial_radix};
            w_adr_eq_mc_ptr     : w_rdata = {20'd0,r_addr};
            w_adr_eq_risr       : w_rdata = {12'd0,i_core_ris[8:5],4'd0,i_core_ris[4:1],7'd0,i_core_ris[0]};
            w_adr_eq_imcr       : w_rdata = {12'd0,r_core_irqen[8:5],4'd0,r_core_irqen[4:1],7'd0,r_core_irqen[0]};
            w_adr_eq_misr       : w_rdata = {12'd0,w_core_mi[8:5],4'd0,w_core_mi[4:1],7'd0,w_core_mi[0]};
            w_adr_eq_rt_code    : w_rdata = {28'd0,i_stop_log};
            w_adr_eq_ram_init_done  :
                                  w_rdata = {31'd0,i_init_done};
            w_adr_eq_rnd_sd     : w_rdata = r_seed;
            w_adr_eq_rc_en      : w_rdata = {31'd0,r_rc_en};
            w_adr_eq_rc_key     : w_rdata = {16'd0,r_rc_key};
            w_adr_eq_rc_data_nonce  :
                                  w_rdata = r_rc_data_nonce;
            w_adr_eq_rc_addr_nonce  :
                                  w_rdata = r_rc_addr_nonce;
            w_adr_eq_version    : w_rdata = {p_PRO_NUM,8'd0,p_MAR_VER,p_MIR_VER};
            w_adr_eq_ram0       : w_rdata = w_r0_rdat;
            w_adr_eq_ram1       : w_rdata = w_r1_rdat;
            default             : w_rdata = {p_AHB_DATA_WIDTH{1'b0}};
        endcase
    end
    assign  o_hready_rls        = w_hready_rls          ;
    assign  o_go                = r_go                  ;
    assign  o_partial_radix     = w_partial_radix       ;
    assign  o_base_radix        = w_base_radix          ;
    assign  o_addr              = r_addr                ;
    assign  o_core_done_clr     = w_core_done_clr       ;
    assign  o_core_irqen        = r_core_irqen          ;
    assign  o_seed              = r_seed                ;
    assign  o_rc_en             = r_rc_en1;
    assign  o_rc_key            = r_rc_key              ;
    assign  o_rc_data_nonce     = r_rc_data_nonce       ;
    assign  o_rc_addr_nonce     = r_rc_addr_nonce       ;
    assign  o_ram0_wr_dat       = w_r0_wdat             ; 
    assign  o_ram0_wr_addr      = w_r0_waddr_o          ;  
    assign  o_ram0_wr_en        = w_r0_wren             ;
    assign  o_ram0_wbe          = w_r0_wbe              ;
    assign  o_ram0_rd_addr      = w_r0_raddr            ; 
    assign  o_ram0_rd_en        = w_r0_rden             ; 
    assign  o_ram1_wr_dat       = w_r1_wdat             ;  
    assign  o_ram1_wr_addr      = w_r1_waddr_o          ;  
    assign  o_ram1_wr_en        = w_r1_wren             ;
    assign  o_ram1_wbe          = w_r1_wbe              ;
    assign  o_ram1_rd_addr      = w_r1_raddr            ; 
    assign  o_ram1_rd_en        = w_r1_rden             ; 
    assign  o_ram_ecc_en        = w_ram_ecc_en          ;  
    assign  o_ram_ecctest_en    = w_ram_ecctest_en      ;
    assign  o_ram_ecc_chkbit    = w_ram_ecc_chkbit      ;
endmodule
module pke_hp_A000Yc              #(
    parameter   A001Yc          =   4096
   ,parameter   A002Yc          =   1
)(
    input   wire                    clk             
   ,input   wire                    rst_n           
   ,input   wire                    A003Yc          
   ,input   wire                    A004Yc          
   ,output  wire                    A005Yc          
   ,output  wire                    A006Yc          
   ,output  wire                    A007Yc          
   ,input   wire    [5:0]           A008Yc          
   ,input   wire    [3:0]           A009Yc          
   ,input   wire    [3:0]           A010Yc          
   ,input   wire    [4:0]           A011Yc          
   ,input   wire    [7:0]           A012Yc          
   ,input   wire    [7:0]           A013Yc          
   ,input   wire    [1:0]           A014Yc  
   ,input   wire                    A015Yc     
